create table if not exists public.erp_qualidade_8d (id uuid primary key default gen_random_uuid(), empresa_id uuid not null references public.erp_empresas(id), codigo text not null, rpnc_id uuid, etapa_atual text not null default 'D1', d1_equipe text not null default '', d2_problema text not null default '', d3_contencao text not null default '', d4_causa_raiz text not null default '', d5_acoes text not null default '', d6_validacao text not null default '', d7_preventivas text not null default '', d8_encerramento text not null default '', status text not null default 'EM_ANALISE', criado_em timestamptz not null default now(), atualizado_em timestamptz not null default now(), unique (empresa_id,codigo)); alter table public.erp_qualidade_8d enable row level security; revoke all on public.erp_qualidade_8d from public, anon; grant select,insert,update,delete on public.erp_qualidade_8d to authenticated; create policy erp_qualidade_8d_tenant on public.erp_qualidade_8d for all to authenticated using (empresa_id=public.erp_current_empresa_id()) with check (empresa_id=public.erp_current_empresa_id());